expression:
local({
  roc_year <- coalesce(
    if_else(as.numeric(w1mobyr) %in% c(97, 99), NA_real_, as.numeric(w1mobyr)),
    if_else(as.numeric(w3mobyr) %in% c(97, 99), NA_real_, as.numeric(w3mobyr))
  )
  roc_year <- carry_within(roc_year, participant_id, as.numeric(.wave))
  recode_values(.wave, "1" ~ 2001.916, "2" ~ 2003.270, "3" ~ 2005.916, "4" ~ 2007.371) - (roc_year + 1911 + 0.5)
})
